find:
.pointTag {
  flex: none;
  font: 500 10px/1 var(--pk-font);
  letter-spacing: 0.1em;
  color: var(--accent);
}

replace:
.pointTag {
  flex: none;
  font: 500 10px/1 var(--pk-font);
  letter-spacing: 0.1em;
  color: var(--pk-lime);
}

.point[data-accent="violet"] .pointTag {
  color: var(--pk-violet);
}

.point[data-accent="amber"] .pointTag {
  color: var(--pk-amber);
}

.point[data-accent="muted"] .pointTag {
  color: var(--pk-ink-muted);
}
